edits.replacement:
#root #keyslist .keysec{ font-size:var(--fs-body); padding-top:var(--sp-3); }
/* v28.xx (cw-xghost) critic c-31 round 10 (pause 25 at 3: "the X is a thin white-bordered square with a heavy glyph ... looks brighter than the title"; Settings 26 at 3: "focus is stacked as four cues, drop the bordered stepper box"; Keys 32 at 3: "the group heading is quieter than its items"). Now: all three header X buttons are ghosts (line-hi border, tx-2 glyph, tx-1 on hover and focus), the focused Settings value loses its box, and the Keys section labels are tx-1. */
#root #pausex, #root #settingsmodal #closesettings, #root #keysmodal #closekeys{ border-color:var(--ui-line-hi); background:transparent; }
#root #pausex::after, #root #settingsmodal #closesettings::after, #root #keysmodal #closekeys::after{ --xc:var(--tx-2); }
#root #pausex:hover::after, #root #pausex:focus-visible::after, #root #settingsmodal #closesettings:hover::after, #root #settingsmodal #closesettings:focus-visible::after, #root #keysmodal #closekeys:hover::after, #root #keysmodal #closekeys:focus-visible::after{ --xc:var(--tx-1); }
#root #setlist .row.dshow:not(.setjump) > button{ border-color:transparent; background:transparent; }
#root #keyslist .keysec{ color:var(--tx-1); }

check:
{v:'VER',what:'the header X buttons are ghosts with a tx-2 glyph, the Keys section labels are tx-1',
 run:function(){
   var bad=[], x, cs, k, sec, tx1, probe, padWas=document.body.classList.contains('padon');
   __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
   try{
     document.body.classList.remove('padon');
     openSettings('display');
     x=document.getElementById('closesettings'); cs=x?getComputedStyle(x):null;
     if(!cs) bad.push('no settings X');
     else {
       if(cs.backgroundColor!=='rgba(0, 0, 0, 0)') bad.push('the settings X has a fill: '+cs.backgroundColor);
       if(cs.borderTopColor!=='rgb(74, 82, 87)') bad.push('the settings X border is '+cs.borderTopColor+', not line-hi');
       var gl=getComputedStyle(x,'::after').backgroundImage;
       if(gl.indexOf('rgb(170, 164, 152)')<0) bad.push('the X glyph is not tx-2: '+gl.slice(0,120));
     }
     document.getElementById('settingsmodal').classList.remove('on'); try{ __topClear(); }catch(_c){}
     keysOpen(false); sec=document.querySelector('#keyslist .keysec');
     if(!sec) bad.push('no Keys section label');
     else {
       probe=document.createElement('i'); probe.style.color='var(--tx-1)'; document.body.appendChild(probe); tx1=getComputedStyle(probe).color; probe.remove();
       if(getComputedStyle(sec).color!==tx1) bad.push('the Keys section label is '+getComputedStyle(sec).color+', not tx-1 '+tx1);
     }
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ var q=document.getElementById('settingsmodal'); if(q) q.classList.remove('on'); q=document.getElementById('keysmodal'); if(q) q.classList.remove('on'); }catch(_k){} try{ __topClear(); }catch(_c){} document.body.classList.toggle('padon',padWas); }
   return bad.length?bad.join('; '):null; }},
